from pathlib import Path
import base64, py_compile, shutil
from datetime import datetime
ROOT=Path(__file__).resolve().parent
APP=ROOT/"app.py"
BACKUP=ROOT/"backups"/"mock-k-def-upgrade"
BLOCKS={k:base64.b64decode(v).decode() for k,v in {'targets': 'TU9DS19ST1NURVJfVEFSR0VUUyA9IHsKICAgICJRQiI6IDIsCiAgICAiUkIiOiA0LAogICAgIldSIjogNCwKICAgICJURSI6IDIsCiAgICAiSyI6IDEsCiAgICAiREVGIjogMSwKfQoK', 'pool': '', 'score': '', 'recs': '', 'advance': '', 'grade': ''}.items()}

def replace_between(text,start_token,end_token,new_block):
    start=text.find(start_token); end=text.find(end_token,start+1)
    if start < 0 or end < 0:
        raise SystemExit(f"STOPPED: missing boundary {start_token} -> {end_token}")
    return text[:start]+new_block+text[end:]

def main():
    original=APP.read_text(encoding="utf-8"); text=original
    if "MOCK_ROSTER_TARGETS =" not in text:
        anchor="def get_db_connection():"
        pos=text.find(anchor)
        if pos < 0: raise SystemExit("STOPPED: get_db_connection anchor missing")
        text=text[:pos]+BLOCKS["targets"]+text[pos:]
    text=replace_between(text,"def mock_pool(","def mock_score(",BLOCKS["pool"])
    text=replace_between(text,"def mock_score(","def mock_recommendations(",BLOCKS["score"])
    text=replace_between(text,"def mock_recommendations(","def insert_mock_pick(",BLOCKS["recs"])
    text=replace_between(text,"def advance_mock_ai(","def mock_grade_simple(",BLOCKS["advance"])
    text=replace_between(text,"def mock_grade_simple(","@app.route('/mockdraft')",BLOCKS["grade"])
    text=text.replace("counts={p:0 for p in ROSTER_TARGETS}","counts={p:0 for p in MOCK_ROSTER_TARGETS}")
    compile(text,str(APP),"exec")
    BACKUP.mkdir(parents=True,exist_ok=True)
    target=BACKUP/f"app.py.{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(APP,target); print("Backup:",target.relative_to(ROOT))
    APP.write_text(text,encoding="utf-8")
    py_compile.compile(str(APP),doraise=True)
    print("PASS: future operational mocks require one K and one DEF in final rounds")
    print("PASS: research simulations and live Draft HQ targets unchanged")
if __name__=="__main__": main()
